          public_ip = '${esc(n.public_ip)}',
          hours_used_month = ROUND((hours_used_month + ${hrsDelta})::numeric, 2),
          updated_at = NOW()
      WHERE region_code = '${esc(n.region_code)}';
    `;
  }
} else if (action === 'START') {
  sql = `
    UPDATE vibebloom_vpn_nodes
    SET status = 'STARTING (Booting AWS Node...)',
        last_started_at = NOW(),
        auto_stop_at = NOW() + INTERVAL '3 hours',
        updated_at = NOW()
    WHERE region_code = '${esc(region)}';
  `;
} else if (action === 'STOP') {
  sql = `
    UPDATE vibebloom_vpn_nodes
    SET status = 'STOPPED ($0/hr Free Tier Idle)',
        auto_stop_at = NULL,
        updated_at = NOW()
    WHERE region_code = '${esc(region)}';
  `;
} else if (action === 'STOP_ALL') {
  sql = `
    UPDATE vibebloom_vpn_nodes
    SET status = 'STOPPED ($0/hr Free Tier Idle)',
        auto_stop_at = NULL,
        updated_at = NOW();
  `;
}

sql += `
  SELECT
    (SELECT COALESCE(json_agg(v ORDER BY CASE v.region_code WHEN 'US' THEN 1 WHEN 'UK' THEN 2 ELSE 3 END), '[]'::json) FROM vibebloom_vpn_nodes v) AS vpn_nodes,
    (SELECT ROUND(COALESCE(SUM(hours_used_month), 0)::numeric, 2) FROM vibebloom_vpn_nodes) AS total_hours_used;
`;

return [{ json: { ok: true, region, action, awsNodes, sqlQuery: sql } }];
